note(153,'Moeda em mil-réis é histórica; integrar regime de dias-multa, não converter valores por palpite.')
note(154,'Referência monetária histórica não é tabela atual de multa; justa causa exige fundamento pertinente, não autorização genérica.')
note('154-a','Redação de2021 retirou referência expressa à violação de mecanismo de segurança; não exigir esse requisito histórico em toda hipótese atual. Mudança gravosa não retroage.')
note(155,'Lei15.397 vigente em4/5/2026: novas penas/repouso noturno. Lei15.517 vigente em23/9/2026: combustíveis nas instalações indicadas,§§10–12 e requisitos de aumentos. Não retroagir agravamento nem duplicar fundamento. Súmula511/STJ condiciona privilégio no qualificado; Súmula567 afasta impossível só pela vigilância.', 'https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15517.htm')
patch(158,simples=rows['art-158']['simples'].replace('Organização criminosa ultraviolenta, paramilitar ou milícia: pena em triplo.','§4º: organização criminosa, grupo paramilitar ou milícia no contexto/finalidade legais; triplo. Não inserir ultraviolenta como requisito que esse parágrafo não traz.'))
note(158,'Súmula96/STJ: extorsão consuma-se independentemente da obtenção da vantagem indevida. §4º exige contexto/finalidade; não presumir pelo grupo nem retroagir pena mais gravosa.')
for n,art in [(165,62),(166,63)]:patch(n,simples=f'Texto do CP remanescente exige integração ao art.{art} da Lei9.605/1998 sobre proteção cultural/ambiental. Não usar pena antiga do CP como regime vigente completo; identificar objeto, proteção e norma posterior.',pontos=[f'Confrontar Lei9.605 art.{art}.','Texto residual não certifica vigência plena do tipo histórico.'],atencao=['Disciplina posterior impede exercício automático que ensine a pena antiga como regra atual. Não certificada aqui toda derrogação/jurisprudência.'],remissoes=['https://www.planalto.gov.br/ccivil_03/leis/l9605.htm'])
patch('168-a',atencao=['§2º tem marcos e requisitos próprios, mas legislação tributária posterior deve ser integrada: não afirmar que só pagamento anterior à fiscalização pode extinguir em todo regime. LC225/2026 traz exceções do devedor contumaz nos§§5º/6º; não confundir suspensão por parcelamento, extinção por pagamento e faculdade do§3º.'])
note(171,'Lei15.397 vigente em4/5/2026 revogou§5º. Não ensinar representação geral como vigente nem retroagir mudança prejudicial a fatos anteriores; regime intertemporal exige análise própria.')
patch(180,atencao=['Distinguir ciência/dolo, atividade comercial e hipótese culposa; expressão deve saber não permite condenação sem elemento subjetivo nem equiparar comércio a culpa automática. §5º revogado pela Lei15.358/2026; caput2 a6 após Lei15.397 vigente4/5/2026. Não retroagir agravamento.'])
note('180-a','Lei15.397 vigente em4/5/2026 ampliou animal doméstico e pena3 a8; exige finalidade típica e elemento subjetivo, não culpa presumida ou retroatividade gravosa.')
for n in [181,182]:note(n,'Integrar183: violência/grave ameaça, estranho participante e vítima com60 ou mais afastam as disposições. Não generalizar toda violência patrimonial familiar sem norma especial e jurisprudência aplicáveis.')
patch(201,simples='O texto histórico do art.201 deve ser integrado ao direito constitucional de greve e Lei7.783/1989. Interrupção de serviço coletivo não autoriza criminalizar automaticamente toda greve; verificar deveres legais, abuso e outros tipos pertinentes.',pontos=['CF9º e Lei7.783: direito de greve e serviços essenciais.','Não ensinar detenção residual como punição universal por greve legítima.'],atencao=['Não certificada toda discussão de recepção ou jurisprudência de greve nesta revisão; treino literal automático bloqueado.'],remissoes=['https://www.planalto.gov.br/ccivil_03/leis/l7783.htm'])
note(204,'A obrigação de nacionalização precisa ser identificada no direito vigente; não criminalizar contratação regular de migrante por nacionalidade. Não certificadas todas as normas complementares setoriais.')
note(213,'A faixa etária do§1º tem redação residual com ou; não ensinar inclusão universal de maior14 isoladamente nem certificar aqui toda fronteira etária por leitura automática. Integrar217-A e jurisprudência específica; treino literal de faixa ambígua bloqueado.')
note('168-a','LC225: exceções penais vigentes em9/1/2026; vacância de90 dias de programas específicos não é vacância geral dessas alterações. Integrar Lei10.684 art.9 e lei no tempo.', 'https://www.planalto.gov.br/ccivil_03/leis/lcp/lcp225.htm')
rows['art-168-a']['remissoes'].append('https://www.planalto.gov.br/ccivil_03/leis/2003/l10.684.htm')
